SET NOCOUNT ON;
SET XACT_ABORT ON;
DECLARE @Now DATETIME2 = SYSDATETIME();
DECLARE @NowShamsi NVARCHAR(30) = CONVERT(NVARCHAR(30), @Now, 120);
DECLARE @Seed NVARCHAR(80) = N'seed-hrm-resume-access';
DECLARE @QueryJson NVARCHAR(MAX) = N'{"Tables": [], "Relations": [], "Filters": [], "CustomConditions": [], "CustomQuery": "DECLARE @CuId BIGINT = TRY_CAST(@CurrentUserId AS BIGINT);\nDECLARE @OrgId BIGINT = (SELECT OrgUnitId FROM [system].[User] WHERE Id = @CuId);\nDECLARE @Roles NVARCHAR(MAX) = (SELECT Roles FROM [system].[User] WHERE Id = @CuId);\nDECLARE @IsAdmin BIT = CASE WHEN EXISTS (SELECT 1 FROM OPENJSON(ISNULL(@Roles, N''[]'')) j WHERE j.value IN (N''admin'', N''Admin'')) THEN 1 ELSE 0 END;\nDECLARE @IsExpert BIT = CASE WHEN @IsAdmin = 1 OR EXISTS (SELECT 1 FROM OPENJSON(ISNULL(@Roles, N''[]'')) j WHERE j.value = N''رزومه - کارشناس توسعه منابع انسانی'') THEN 1 ELSE 0 END;\nDECLARE @IsManager BIT = CASE WHEN EXISTS (SELECT 1 FROM OPENJSON(ISNULL(@Roles, N''[]'')) j WHERE j.value = N''رزومه - مدیر/سرپرست واحد درخواست کننده نیرو'') THEN 1 ELSE 0 END;\nDECLARE @IsHrm BIT = CASE WHEN EXISTS (SELECT 1 FROM OPENJSON(ISNULL(@Roles, N''[]'')) j WHERE j.value = N''رزومه - مدیر/سرپرست توسعه منابع انسانی'') THEN 1 ELSE 0 END;\nDECLARE @IsBoard BIT = CASE WHEN EXISTS (SELECT 1 FROM OPENJSON(ISNULL(@Roles, N''[]'')) j WHERE j.value = N''رزومه - هیئت مدیره'') THEN 1 ELSE 0 END;\nDECLARE @IsOffice BIT = CASE WHEN EXISTS (SELECT 1 FROM OPENJSON(ISNULL(@Roles, N''[]'')) j WHERE j.value = N''رزومه - کارشناس امور اداری تهران/کارخانه'') THEN 1 ELSE 0 END;\nDECLARE @Mode INT = CASE WHEN @IsExpert = 1 THEN 1 WHEN @IsManager = 1 THEN 2 WHEN @IsHrm = 1 THEN 3 WHEN @IsBoard = 1 THEN 4 WHEN @IsOffice = 1 THEN 5 ELSE 0 END;\n--!--mainsection\nSELECT\n [t1].[Id] AS [t1_Id],\n [t1].[HtsId] AS [t1_HtsId],\n [sr].[HtsId] AS [t1_StaffRequestId],\n LTRIM(RTRIM(CONCAT(ISNULL([rp].[Name], N''''), N'' '', ISNULL([rp].[Family], N'''')))) AS [t1_RequestPerson],\n CASE WHEN EXISTS (SELECT 1 FROM [Hrm].[ResumeAttachment] a WHERE a.ResumeId = [t1].[Id]) OR [t1].[ResumeFileId] IS NOT NULL THEN CAST(1 AS bit) ELSE CAST(0 AS bit) END AS [t1_HasAttachment],\n LTRIM(RTRIM(CONCAT(ISNULL([t1].[Name], N''''), N'' '', ISNULL([t1].[Family], N'''')))) AS [t1_FullName],\n CASE [t1].[Organization] WHEN 1185 THEN N''هوایار'' WHEN 1186 THEN N''هوایار کنترل پیشرو'' WHEN 1187 THEN N''هوایار سوخت'' WHEN 1188 THEN N''هوایار گاز'' ELSE N'''' END AS [t1_Organization],\n [op].[Title] AS [t1_Post],\n CASE [t1].[Status] WHEN 2240 THEN N''دعوت به مصاحبه'' WHEN 2241 THEN N''عدم تایید'' WHEN 2242 THEN N''در دست بررسی'' WHEN 2243 THEN N''رزرو'' ELSE N'''' END AS [t1_Status],\n [t1].[InExpertCartable] AS [t1_InExpertCartable],\n [t1].[InManagerCartable] AS [t1_InManagerCartable],\n [t1].[InHrmManagerCartable] AS [t1_InHrmManagerCartable],\n [t1].[InBoardOfDirectorsCartable] AS [t1_InBoardOfDirectorsCartable],\n [t1].[InOfficeExpertCartable] AS [t1_InOfficeExpertCartable],\n CASE [t1].[ResumeStatus] WHEN 52 THEN N''بایگانی'' WHEN 53 THEN N''نامناسب'' WHEN 54 THEN N''رزرو'' WHEN 73 THEN N''جذب'' WHEN 1715 THEN N''عدم مصاحبه'' WHEN 1716 THEN N''عدم حضور در مصاحبه'' WHEN 1717 THEN N''انصراف'' WHEN 1718 THEN N''برای پست های سازمانی هوایار مناسب نمی باشد'' ELSE N'''' END AS [t1_ResumeStatus],\n CASE [t1].[Sex] WHEN 2 THEN N''مرد'' ELSE N''زن'' END AS [t1_Sex],\n CASE [t1].[Education] WHEN 1 THEN N''بیسواد'' WHEN 2 THEN N''ابتدائی'' WHEN 3 THEN N''سیکل'' WHEN 4 THEN N''زیردیپلم'' WHEN 5 THEN N''دیپلم'' WHEN 6 THEN N''فوق دیپلم'' WHEN 7 THEN N''لیسانس'' WHEN 8 THEN N''فوق لیسانس'' WHEN 9 THEN N''دکتری'' WHEN 10 THEN N''فوق دکتری'' WHEN 11 THEN N''دانشجوی (فوق دیپلم)'' WHEN 12 THEN N''دانشجوی (لیسانس)'' WHEN 13 THEN N''دانشجوی (فوق لیسانس)'' WHEN 14 THEN N''دانشجوی (دکتری)'' ELSE N'''' END AS [t1_Education],\n [sc].[Title] AS [t1_StudyCourse],\n [t1].[BirthDate] AS [t1_BirthDate],\n [city].[Name] AS [t1_City],\n [t1].[PhoneNumber] AS [t1_Phone],\n [t1].[MobileNumber] AS [t1_Mobile],\n [src].[Title] AS [t1_Source],\n LTRIM(RTRIM(CONCAT(ISNULL([pr].[Name], N''''), N'' '', ISNULL([pr].[Family], N'''')))) AS [t1_Presenter],\n [t1].[ResumeReviewDeadline] AS [t1_Deadline],\n [t1].[ManagerDescription] AS [t1_ManagerDescription],\n [t1].[PriorityToInvite] AS [t1_Priority],\n [t1].[RecommendedDateInText] AS [t1_RecommendedDate],\n [t1].[RecommendedTimeInText] AS [t1_RecommendedTime],\n [ou].[Title] AS [t1_Unit],\n [t1].[ReasonForIntroduction] AS [t1_Reason],\n [sj].[Title] AS [t1_SuitableJob],\n [t1].[ReasonForSuitableJob] AS [t1_SuitableReason],\n [t1].[CancelByJobApplicant] AS [t1_Cancel],\n [t1].[JobApplicantCancelReason] AS [t1_CancelReason],\n [t1].[IsInvitedToInterview] AS [t1_Invited],\n [t1].[SessionDate] AS [t1_SessionDate],\n [t1].[SessionTime] AS [t1_SessionTime],\n [t1].[SessionPlace] AS [t1_SessionPlace],\n [t1].[BeneficiaryNames] AS [t1_Beneficiaries],\n [t1].[ExpertDescription] AS [t1_ExpertDescription],\n LTRIM(RTRIM(CONCAT(ISNULL([sp].[Name], N''''), N'' '', ISNULL([sp].[Family], N'''')))) AS [t1_SpecName],\n CASE [t1].[SpecializedInterviewStatus] WHEN 2244 THEN N''عدم حضور مصاحبه شونده بدون هماهنگی قبلی'' WHEN 2245 THEN N''تایید'' WHEN 2246 THEN N''عدم تایید'' WHEN 2247 THEN N''در دست بررسی'' WHEN 2248 THEN N''رزرو'' ELSE N'''' END AS [t1_SpecStatus],\n LTRIM(RTRIM(CONCAT(ISNULL([hr].[Name], N''''), N'' '', ISNULL([hr].[Family], N'''')))) AS [t1_HrName],\n CASE [t1].[HrInterviewerStatus] WHEN 2249 THEN N''عدم حضور مصاحبه شونده بدون هماهنگی قبلی'' WHEN 2250 THEN N''تایید'' WHEN 2251 THEN N''عدم تایید'' WHEN 2252 THEN N''نظر منابع انسانی مثبت بوده ولی مصاحبه شونده مبلغ و شرایط کاری را نپذیرفته'' ELSE N'''' END AS [t1_HrStatus],\n [t1].[ContractAmount] AS [t1_Contract],\n [t1].[HrInterviewerDescription] AS [t1_HrDescription],\n [t1].[CreatedByName] AS [t1_CreatedBy],\n [t1].[ResumeShamsiDate] AS [t1_ResumeDate],\n [t1].[ResumeTime] AS [t1_ResumeTime],\n [t1].[ModifiedByName] AS [t1_UpdatedBy],\n [t1].[HrInterviewerId] AS [t1_HrInterviewerId],\n [t1].[PreviousCompanyName] AS [t1_PreviousCompanyName]\nFROM [Hrm].[Resume] AS [t1]\nLEFT JOIN [Hrm].[StaffRequest] AS [sr] ON [sr].[Id] = [t1].[StaffRequestId]\nLEFT JOIN [Hcm].[Personel] AS [rp] ON [rp].[Id] = [sr].[RequestPersonelId]\nLEFT JOIN [Hrm].[OrgPost] AS [op] ON [op].[Id] = [t1].[InterestedPostId]\nLEFT JOIN [Hrm].[StudyCourse] AS [sc] ON [sc].[Id] = [t1].[StudyCourseId]\nLEFT JOIN [Gnr].[Region] AS [city] ON [city].[Id] = [t1].[CityId]\nLEFT JOIN [Hrm].[IncomingSource] AS [src] ON [src].[Id] = [t1].[IncomingSourceId]\nLEFT JOIN [Hcm].[Personel] AS [pr] ON [pr].[Id] = [t1].[RepresentingPersonelId]\nLEFT JOIN [Hrm].[OrgUnit] AS [ou] ON [ou].[Id] = [t1].[UnitIntroducedId]\nLEFT JOIN [Hcm].[Job] AS [sj] ON [sj].[Id] = [t1].[SuitableForJobId]\nLEFT JOIN [Hcm].[Personel] AS [sp] ON [sp].[Id] = [t1].[SpecializedInterviewerId]\nLEFT JOIN [Hcm].[Personel] AS [hr] ON [hr].[Id] = [t1].[HrInterviewerId]\nWHERE @Mode = 1\n OR (@Mode = 2 AND [t1].[InManagerCartable] = 1 AND ([sr].[RequestUserId] = @CuId OR [sr].[RequestOrgUnitId] = @OrgId))\n OR (@Mode = 3 AND [t1].[InHrmManagerCartable] = 1)\n OR (@Mode = 4 AND [t1].[InBoardOfDirectorsCartable] = 1)\n OR (@Mode = 5 AND [t1].[InOfficeExpertCartable] = 1)\n", "Parameters": [], "Selects": null}';
