DECLARE @Events NVARCHAR(MAX) = N'{"onSelectedRow":"","onRowAdded":""}';

BEGIN TRY
    BEGIN TRANSACTION;
    IF EXISTS (SELECT 1 FROM system.SavedQuery WHERE Name = N'Hrm_Resume_List')
        UPDATE system.SavedQuery
        SET Title = N'مدیریت رزومه (New)', EntityFullName = N'entities.app.hrm.resume', Mode = 1, Type = 1,
            QueryJson = @QueryJson, ColumnsJson = @Columns, ActionOptions = @Actions, CustomActionButtonsJson = @Buttons,
            EventScriptsJson = @Events, DiagramJson = N'{}',
            ModifiedById = 1, ModifiedByName = @Seed, ModifiedDateMiladiDateTime = @Now, ModifiedDateShamsiDateTime = @NowShamsi
        WHERE Name = N'Hrm_Resume_List';
    ELSE
        INSERT INTO system.SavedQuery
            (Name, Title, EntityFullName, Mode, Type, QueryJson, ColumnsJson, ActionOptions, CustomActionButtonsJson, EventScriptsJson, DiagramJson,
             CreatedById, CreatedByName, ModifiedById, ModifiedByName, CreatedOnMiladiDateTime, ModifiedDateMiladiDateTime, CreatedOnShamsiDateTime, ModifiedDateShamsiDateTime, IsActive)
        VALUES
            (N'Hrm_Resume_List', N'مدیریت رزومه (New)', N'entities.app.hrm.resume', 1, 1, @QueryJson, @Columns, @Actions, @Buttons, @Events, N'{}',
             1, @Seed, 1, @Seed, @Now, @Now, @NowShamsi, @NowShamsi, 1);

    DECLARE @Roles TABLE (Name NVARCHAR(200));
    INSERT INTO @Roles VALUES
        (N'رزومه - کارشناس توسعه منابع انسانی'),
        (N'رزومه - مدیر/سرپرست واحد درخواست کننده نیرو'),
        (N'رزومه - مدیر/سرپرست توسعه منابع انسانی'),
        (N'رزومه - هیئت مدیره'),
        (N'رزومه - کارشناس امور اداری تهران/کارخانه');

    INSERT INTO system.Role (Name, Title, CreatedById, CreatedByName, ModifiedById, ModifiedByName, CreatedOnMiladiDateTime, ModifiedDateMiladiDateTime, CreatedOnShamsiDateTime, ModifiedDateShamsiDateTime, IsActive)
    SELECT r.Name, r.Name, 1, @Seed, 1, @Seed, @Now, @Now, @NowShamsi, @NowShamsi, 1
    FROM @Roles r
    WHERE NOT EXISTS (SELECT 1 FROM system.Role x WHERE x.Name = r.Name);

    DECLARE @Act TABLE (Suffix NVARCHAR(40), AType INT, IType INT);
    INSERT INTO @Act VALUES
        (N'list', 1, 1), (N'fetchdata', 2, 2), (N'new', 1, 4), (N'add', 2, 4),
        (N'edit', 1, 5), (N'update', 2, 5), (N'delete', 2, 6), (N'exporttoexcel', 2, 1000);

    DELETE ra
    FROM system.RoleAccess ra
    INNER JOIN system.Role r ON r.Id = ra.RoleId
    INNER JOIN @Roles n ON n.Name = r.Name
    WHERE ra.Path LIKE N'/panel/hrm/resume/%' OR (ra.ActionAccessType = 3 AND ra.EntityName = N'Entities.App.Hrm.Resume');

    INSERT INTO system.RoleAccess
        (Path, ActionAccessType, ActionAccessItemType, EntityName, DisplayName, RowId, RoleId,
         CreatedById, ModifiedById, CreatedByName, ModifiedByName, CreatedOnMiladiDateTime, CreatedOnShamsiDateTime, ModifiedDateMiladiDateTime, ModifiedDateShamsiDateTime, IsActive)
    SELECT N'/panel/hrm/resume/' + a.Suffix, a.AType, a.IType, N'Entities.App.Hrm.Resume', a.Suffix, NULL, r.Id,
           1, 1, @Seed, @Seed, @Now, @NowShamsi, @Now, @NowShamsi, 1
    FROM system.Role r
    INNER JOIN @Roles n ON n.Name = r.Name
    CROSS JOIN @Act a;

    INSERT INTO system.RoleAccess
        (Path, ActionAccessType, ActionAccessItemType, EntityName, DisplayName, RowId, RoleId,
         CreatedById, ModifiedById, CreatedByName, ModifiedByName, CreatedOnMiladiDateTime, CreatedOnShamsiDateTime, ModifiedDateMiladiDateTime, ModifiedDateShamsiDateTime, IsActive)
    SELECT N'dataProfile_' + CAST(q.Id AS NVARCHAR(20)), 3, 7, N'Entities.App.Hrm.Resume', q.Title, q.Id, r.Id,
           1, 1, @Seed, @Seed, @Now, @NowShamsi, @Now, @NowShamsi, 1
    FROM system.SavedQuery q
    CROSS JOIN system.Role r
    INNER JOIN @Roles n ON n.Name = r.Name
    WHERE q.Name = N'Hrm_Resume_List';

    DECLARE @Leaf NVARCHAR(MAX) = N'{"text":"عملیات مدیریت رزومه (New)","icon":"ki-profile-user ki-outline","iconColor":"#c084fc","path":"/panel/hrm/resume/list","a_attr":{"href":"/panel/hrm/resume/list"},"data":{"iconColor":"#c084fc","path":"/panel/hrm/resume/list"},"children":[]}';
    DECLARE @AllContent NVARCHAR(MAX) = (SELECT Content FROM system.SystemMenu WHERE Name = N'AllMenus');
    DECLARE @HrIdx INT = (SELECT TOP 1 CAST(j.[key] AS INT) FROM OPENJSON(@AllContent) j WHERE JSON_VALUE(j.value, '$.text') = N'منابع انسانی');
    DECLARE @Hr NVARCHAR(MAX) = (SELECT TOP 1 CAST(j.value AS NVARCHAR(MAX)) FROM OPENJSON(@AllContent) j WHERE CAST(j.[key] AS INT) = @HrIdx);
    DECLARE @HrChildren NVARCHAR(MAX) = JSON_QUERY(@Hr, '$.children');
    DECLARE @RecIdx INT = (SELECT TOP 1 CAST(c.[key] AS INT) FROM OPENJSON(@HrChildren) c WHERE JSON_VALUE(c.value, '$.text') = N'سیستم جذب و استخدام');
    DECLARE @Rec NVARCHAR(MAX) = (SELECT TOP 1 CAST(c.value AS NVARCHAR(MAX)) FROM OPENJSON(@HrChildren) c WHERE CAST(c.[key] AS INT) = @RecIdx);
    DECLARE @RecChildren NVARCHAR(MAX) = JSON_QUERY(@Rec, '$.children');
    IF NOT EXISTS (SELECT 1 FROM OPENJSON(ISNULL(@RecChildren, N'[]')) c WHERE JSON_VALUE(c.value, '$.text') = N'عملیات مدیریت رزومه (New)')
    BEGIN
        SET @RecChildren = JSON_MODIFY(ISNULL(@RecChildren, N'[]'), 'append $', JSON_QUERY(@Leaf));
        SET @Rec = JSON_MODIFY(@Rec, '$.children', JSON_QUERY(@RecChildren));
        SET @HrChildren = JSON_MODIFY(@HrChildren, '$[' + CAST(@RecIdx AS NVARCHAR(10)) + ']', JSON_QUERY(@Rec));
        SET @Hr = JSON_MODIFY(@Hr, '$.children', JSON_QUERY(@HrChildren));
        SET @AllContent = JSON_MODIFY(@AllContent, '$[' + CAST(@HrIdx AS NVARCHAR(10)) + ']', JSON_QUERY(@Hr));
        UPDATE system.SystemMenu SET Content = @AllContent, ModifiedById = 1, ModifiedByName = @Seed, ModifiedDateMiladiDateTime = @Now, ModifiedDateShamsiDateTime = @NowShamsi WHERE Name = N'AllMenus';
    END

    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    DECLARE @Err NVARCHAR(4000) = ERROR_MESSAGE();
    RAISERROR(@Err, 16, 1);
    RETURN;
END CATCH;

SELECT Name, Title FROM system.SavedQuery WHERE Name = N'Hrm_Resume_List';
SELECT r.Name, COUNT(ra.Id) AS AccessRows
FROM system.Role r
LEFT JOIN system.RoleAccess ra ON ra.RoleId = r.Id AND ra.Path LIKE N'/panel/hrm/resume/%'
WHERE r.Name LIKE N'رزومه - %'
GROUP BY r.Name;
